from ..widgets.widgets import BetterCanvas
from ..widgets.widgets import Tooltip
from ..utils.logger import logger

import tkinter as tk
import itertools
from tkinter import ttk

from PIL import Image, ImageTk
from pathlib import Path
import os
import re


def sorting_available_rmods_key(s):
    return int(re.search(r'RMOD-(\d+)', s).group(1))


class CellsFrame(ttk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="cell_frame_section", borderwidth=1, relief="ridge", *args, **kwargs)
        self.model = model
        self.available_rmods_list = []
        self.cells_dictionary = {}
        self.cells_iterator = 1
        self.icons = self.__get_icons()
        self._initial_setup()

    def get_configuration(self):
        return {i: cell.get_configuration() for i, cell in self.cells_dictionary.items()}

    def get_validation_log(self, selected_profile):
        validation_log = []
        for i, cell in self.cells_dictionary.items():
            if not cell.is_fully_configured:
                validation_log.append(f'CELL-{i} is not fully configured')
        return validation_log

    def _initial_setup(self):
        cells_label = ttk.Label(
            self,
            text=(
                "Radio Module            " + "      ".join(f"ANT{i}" for i in range(1, 9))
            ),
            font=('Helvetica', 12, 'bold'),
            name="cells_frame_label",
        )
        add_new_cell_button = ttk.Button(
            self, text="Add Cell", command=lambda: self._add_cell(event=True), image=self.icons['cell_plus'], name='add_cell_frame'
        )
        Tooltip(add_new_cell_button, text='Add Cell')
        separator = ttk.Separator(
            self, orient='horizontal', name="header_separator"
        )
        cells_canvas = BetterCanvas(
            self, bg="white", borderwidth=0, height=636, name="cells_canvas"
        )
        cells_scrollbar = ttk.Scrollbar(
            self, orient=tk.VERTICAL, command=cells_canvas.yview, name="cells_scrollbar"
        )
        cells_frame = ttk.Frame(
            cells_canvas, name="cells_frame"
        )
        cells_canvas.create_window((0, 0), window=cells_frame)
        cells_canvas.configure(yscrollcommand=cells_scrollbar.set)

        cells_label.grid(column=0, row=0, sticky="sw", padx=(14, 0), ipady=10, columnspan=2)
        add_new_cell_button.grid(row=0, column=3, padx=(113, 0), sticky="nsew")
        separator.grid(row=1, sticky="ew", columnspan=4)
        cells_canvas.grid(row=2, sticky="nsew", columnspan=4)
        cells_scrollbar.grid(row=2, column=3, sticky="nse")

        cells_frame.bind("<Configure>", self.update_canvas)  # is it necessary?

        cells_canvas.bind('<Enter>', self._bound_to_mousewheel)
        cells_canvas.bind('<Leave>', self._unbound_to_mousewheel)

    @property
    def cells_canvas(self):
        return self.children['cells_canvas']

    @property
    def cells_scrollbar(self):
        return self.children['cells_scrollbar']

    def update_canvas(self, _event=None):
        self.cells_canvas.configure(scrollregion=self.cells_canvas.bbox("all"))
        if self.cells_canvas.yview() == (0.0, 1.0):
            self.cells_canvas.yview_moveto(1.0)

    def _bound_to_mousewheel(self, _event):
        self.cells_canvas.bind_all("<Button-4>", lambda event: self.cells_canvas.yview_scroll(int(-1 * event.num), 'units'))
        self.cells_canvas.bind_all("<Button-5>", lambda event: self.cells_canvas.yview_scroll(int(event.num), 'units'))

    def _unbound_to_mousewheel(self, _event):
        self.cells_canvas.unbind_all("<Button-4>")
        self.cells_canvas.unbind_all("<Button-5>")

    def _add_cell(self, connections=None, ch_bw="", earfcn="", cell_technology=None, mplane_only=False, event=False):
        if connections is None:
            connections = [('', '', '', '', '', '', '', '', '')]
        number_of_cells = len(self.cells_dictionary)
        next_cell_id = number_of_cells + 1

        parent = self.children['cells_canvas'].children['cells_frame']
        single_cell_frame = SingleCellFrame(
            parent, connections, ch_bw, earfcn, cell_technology, mplane_only, self.available_rmods_list,
            self.icons, text=f"CELL-{next_cell_id}", borderwidth=0, font=('Helvetica 9'),
            bg='white', name=f"cell_{self.cells_iterator}"
        )
        self.cells_dictionary[next_cell_id] = single_cell_frame
        single_cell_frame.grid(column=0, row=next_cell_id, sticky="new")
        self.cells_iterator += 1
        if event:
            logger.info(f"Adding CELL to {self}")
            self.event_generate('<<PostAddCell>>')

    def reset(self):
        new_cells_dictionary = {}
        for i, cell in sorted(self.cells_dictionary.items(), key=lambda item: item[0]):
            if i == 1:
                cell._reset()
                new_cells_dictionary[1] = cell
            else:
                cell.destroy()
        self.cells_dictionary = new_cells_dictionary
        self.update_canvas()

    def full_reset(self):
        for i, cell in sorted(self.cells_dictionary.items(), key=lambda item: item[0]):
            cell.destroy()
        self.cells_dictionary = {}

    def rearrange(self):
        new_cells_dictionary = {}
        for i, (idx, cell) in zip(itertools.count(1), sorted(self.cells_dictionary.items(), key=lambda item: item[0])):
            cell.grid(row=i, sticky="new", column=0, columnspan=2)
            new_cells_dictionary[i] = cell
            cell.configure(text=f"CELL-{i}")
        self.cells_scrollbar.set(0, 1)
        self.cells_dictionary = new_cells_dictionary

    def __get_icons(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        cell_plus = Image.open(graphic_src_path / "cell_plus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        cell_plus_image = ImageTk.PhotoImage(cell_plus, master=self)

        cell_minus = Image.open(graphic_src_path / "cell_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        cell_minus_image = ImageTk.PhotoImage(cell_minus)

        plus_sign = Image.open(graphic_src_path / "large_plus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        plus_sign_image = ImageTk.PhotoImage(plus_sign)

        minus_sign = Image.open(graphic_src_path / "large_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        minus_sign_image = ImageTk.PhotoImage(minus_sign)

        refresh_sign = Image.open(graphic_src_path / "refresh_sign.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        refresh_sign_image = ImageTk.PhotoImage(refresh_sign)

        return {
            'cell_plus': cell_plus_image,
            'cell_minus': cell_minus_image,
            'plus_sign': plus_sign_image,
            'minus_sign': minus_sign_image,
            'refresh_sign': refresh_sign_image
        }

    # flake8: noqa: C901
    def update_available_rmods(self, available_rmods_list, rmod_idx=None):
        for cell in self.cells_dictionary.values():
            intra_cell_occupied_rmods = []
            for connection in cell.connection_dict.values():
                rmod_cb = connection.children['rmod']
                current_rmod_name = rmod_cb.get()
                if current_rmod_name:
                    current_rmod_idx = re.search(r'(\d+)', current_rmod_name).group(1)
                    if rmod_idx:
                        if current_rmod_idx == rmod_idx:
                            connection._reset(event=False)
                        elif int(current_rmod_idx) < int(rmod_idx):
                            intra_cell_occupied_rmods += [current_rmod_name]
                        else:
                            new_rmod_name = re.search(r'(\S+)', current_rmod_name).group(1) + f' (RMOD-{int(current_rmod_idx) - 1})'
                            rmod_cb.set(new_rmod_name)
                            intra_cell_occupied_rmods += [new_rmod_name]
                    else:
                        intra_cell_occupied_rmods += [current_rmod_name]
            for connection in cell.connection_dict.values():
                rmod_cb = connection.children['rmod']
                current_rmod_name = rmod_cb.get()
                if current_rmod_name and current_rmod_name in available_rmods_list:
                    rmod_cb['values'] = sorted(list(
                        set(available_rmods_list) - set(intra_cell_occupied_rmods)) + [current_rmod_name], key=sorting_available_rmods_key
                    )
                elif current_rmod_name:
                    connection._reset(event=False)
                    rmod_cb['values'] = sorted(
                        set(available_rmods_list) - set(intra_cell_occupied_rmods), key=sorting_available_rmods_key
                    )
                else:
                    rmod_cb['values'] = sorted(
                        set(available_rmods_list) - set(intra_cell_occupied_rmods), key=sorting_available_rmods_key
                    )
        self.available_rmods_list = available_rmods_list

    def update_selected_antennas(self):
        for antenna in self.cells_dictionary.values():
            for connection in antenna.connection_dict.values():
                try:
                    selected_rmod = re.search(r'(\S+)', connection.children['rmod'].get()).group(1)
                    number_of_available_antls = int(self.model.rmods_info[selected_rmod]['antenna_count'])
                    for i in range(0, number_of_available_antls):
                        connection.antl_list[i].config(state="readonly")
                    for i in range(number_of_available_antls, 8):
                        connection.antl_list[i].config(state="disabled")
                except AttributeError:
                    continue

    def update_antennas_after_rmod_selection(self, event):
        connection_frame = event.widget.master
        selected_rmod = re.search(r'(\S+)', event.widget.get()).group(1)
        number_of_available_antls = int(self.model.rmods_info[selected_rmod]['antenna_count'])
        antl_list = connection_frame.antl_list
        for antl in antl_list[:number_of_available_antls]:
            antl.set("")
            antl.config(state="readonly")
        for antl in antl_list[number_of_available_antls:]:
            antl.set("")
            antl.config(state="disabled")

    def update_available_rmods_and_reset_changed_rmod(self, available_rmods_list, rmod_idx):
        for cell in self.cells_dictionary.values():
            intra_cell_occupied_rmods = []
            for connection in cell.connection_dict.values():
                rmod_cb = connection.children['rmod']
                current_rmod_name = rmod_cb.get()
                if current_rmod_name:
                    intra_cell_occupied_rmods += [current_rmod_name]
            for connection in cell.connection_dict.values():
                rmod_cb = connection.children['rmod']
                current_rmod_name = rmod_cb.get()
                if current_rmod_name:
                    if rmod_idx == re.search(r'(\d+)', current_rmod_name).group(1):
                        connection._reset()
                        rmod_cb['values'] = sorted(
                            set(available_rmods_list) - set(intra_cell_occupied_rmods), key=sorting_available_rmods_key)
                    else:
                        rmod_cb['values'] = sorted(list(
                            set(available_rmods_list) - set(intra_cell_occupied_rmods)) + [current_rmod_name], key=sorting_available_rmods_key)
                else:
                    rmod_cb['values'] = sorted(
                        set(available_rmods_list) - set(intra_cell_occupied_rmods), key=sorting_available_rmods_key)
        self.available_rmods_list = available_rmods_list


class SingleCellFrame(tk.LabelFrame):
    def __init__(self, parent, connections, ch_bw, earfcn, cell_technology, mplane_only, available_rmods_list, icons, **kwargs):
        super().__init__(parent, labelanchor="nw", **kwargs)
        self.icons = icons
        self.available_rmods_list = available_rmods_list
        self.connection_dict = {}
        self.connection_iterator = 1
        self.cell_tech = tk.StringVar()
        self.mplane_only = tk.BooleanVar()
        self._initial_setup(connections, ch_bw, earfcn, cell_technology, mplane_only)

    @property
    def is_fully_configured(self):
        for i, connection in self.connection_dict.items():
            if not connection.is_fully_configured:
                return False
        return all((self.children["ch_bw_combobox"].get(), self.children["earfcn_entry"].get(), self.cell_tech.get()))

    @property
    def is_fdd(self):
        return str(self.cell_tech.get()) == 'FDD'

    def get_configuration(self):
        cell_params_dict = {}
        for i, connection in self.connection_dict.items():
            cell_params_dict[i] = connection.get_configuration()
        cell_params_dict['ch_bw'] = self.children["ch_bw_combobox"].get()
        cell_params_dict["earfcn"] = self.children["earfcn_entry"].get()
        cell_params_dict["cell_technology"] = self.cell_tech.get()
        cell_params_dict["mplane_only"] = self.mplane_only.get()
        return cell_params_dict

    def _initial_setup(self, connections, ch_bw, earfcn, cell_technology, mplane_only):
        cell_connection_frame = ttk.Frame(
            self, borderwidth=0, relief="flat", name="cell_connection_frame"
        )
        cell_connection_frame.grid(row=0, column=0, sticky="new", columnspan=12)
        first_connection_frame = connections[0]
        single_cell_connection = SingleCellConnectionFrame(
            cell_connection_frame, first_connection_frame, self.available_rmods_list, self.icons,
            borderwidth=0, relief="ridge", name=f"single_cell_connection_{self.connection_iterator}"
        )
        self.connection_iterator += 1
        self.connection_dict[1] = single_cell_connection
        single_cell_connection.grid(sticky="new", pady=2, column=0, columnspan=11)

        add_connection_button = ttk.Button(
            self, text="Add connection", name="add_connection_button", image=self.icons['plus_sign'],
            command=lambda: self._add_connection_frame(event=True)
        )
        Tooltip(add_connection_button, text='Add Single Connection')

        delete_cell_button = ttk.Button(
            self, text="Delete CELL", name="delete_cell", command=lambda: self._destroy_cell(event=True), image=self.icons['cell_minus']
        )
        Tooltip(delete_cell_button, text='Delete Cell')

        reset_cell_button = ttk.Button(
            self, text="Reset CELL", name="reset_cell", command=lambda: self._reset(event=True), image=self.icons['refresh_sign']
        )
        Tooltip(reset_cell_button, text='Reset Cell')

        ch_bw_combobox = ttk.Combobox(
            self, values=["1.4 MHz", "3 MHz", "5 MHz", "10 MHz", "15 MHz", "20 MHz"], width=7, state="readonly", name="ch_bw_combobox"
        )
        ch_bw_combobox.set(ch_bw)

        earfcn_entry = ttk.Entry(
            self, width=8, name="earfcn_entry"
        )
        earfcn_entry.insert(0, earfcn)

        if cell_technology:
            self.cell_tech.set(cell_technology)

        fdd_cell_radiobutton = ttk.Radiobutton(
            self, text="FDD", variable=self.cell_tech, value="FDD", command=lambda: self.event_generate('<<RequireValidation>>')
        )
        tdd_cell_radiobutton = ttk.Radiobutton(
            self, text="TDD", variable=self.cell_tech, value="TDD", command=lambda: self.event_generate('<<RequireValidation>>')
        )
        Tooltip(fdd_cell_radiobutton, text='Set Cell Technology')
        Tooltip(tdd_cell_radiobutton, text='Set Cell Technology')

        self.mplane_only.set(mplane_only)
        mplane_only_checkbutton = ttk.Checkbutton(
            self, text='M-Plane only?', variable=self.mplane_only,
            onvalue=True, offvalue=False, name='mplane_only_checkbutton'
        )
        Tooltip(mplane_only_checkbutton, text='Select if cell must be M-Plane only')

        def validate_entry(inp):
            if inp.isdigit():
                return True
            elif inp == "":
                return True
            else:
                return False

        delete_cell_button.grid(row=2, column=0, sticky="nsw", pady=3)
        reset_cell_button.grid(row=2, column=1, sticky="nsw", pady=3)

        ttk.Label(self, text=" CH BW: ").grid(row=2, column=2, sticky="nsw", pady=3, padx=(70, 0))

        ch_bw_combobox.grid(row=2, column=3, sticky="nsw", pady=3)

        ttk.Label(self, text=" EARFCN: ").grid(row=2, column=4, sticky="nsw", pady=3)

        earfcn_entry.grid(row=2, column=5, sticky="nsw", pady=3)
        fdd_cell_radiobutton.grid(row=2, column=6, sticky="nsw", pady=3)
        tdd_cell_radiobutton.grid(row=2, column=7, sticky="nsw", padx=(0, 183), pady=3)
        add_connection_button.grid(row=2, column=11, sticky="nse", pady=3)
        mplane_only_checkbutton.grid(row=2, column=7, sticky="nse", padx=(0, 45))

        separator_h = ttk.Separator(self, orient='horizontal')
        separator_h.grid(row=3, sticky="ew", columnspan=12)
        for connection in connections[1:]:
            self._add_connection_frame(connection, generate_event=False)
        entry = self.register(validate_entry)
        earfcn_entry.config(validate='key', validatecommand=(entry, '%P'))

    def rearrange(self):
        new_connections_dict = {}
        for i, (idx, connection) in zip(itertools.count(1), sorted(self.connection_dict.items(), key=lambda item: item[0])):
            connection.grid(row=i, sticky="new", pady=2, column=0, columnspan=2)
            new_connections_dict[i] = connection
        self.connection_dict = new_connections_dict

    def _destroy_cell(self, event=False):
        number_of_configured_cells = len(self.__get_cells_frame().cells_dictionary)
        if event:
            logger.info(f"Deleting Cell {self}")
        if number_of_configured_cells > 1:
            self._destroy(event)
        else:
            self._reset()

    def _destroy(self, event=True):
        configured_cells = self.__get_cells_frame().cells_dictionary
        current_id = self._get_current_id(configured_cells)
        configured_cells.pop(current_id)
        self.forget()
        self.__get_cells_frame().rearrange()
        if event:
            self.event_generate('<<PostResetDeleteCell>>')
        self.destroy()

    def _reset(self, event=False):
        new_connection_dict = {}
        self.children['earfcn_entry'].delete(0, tk.END)
        self.children['ch_bw_combobox'].set('10 MHz')
        self.mplane_only.set(False)
        self.cell_tech.set("FDD")
        for i, connection in self.connection_dict.items():
            if i == 1:
                connection._reset()
                new_connection_dict[i] = connection
            if i > 1:
                connection.destroy()
        self.connection_dict = new_connection_dict
        if event:
            logger.info(f"Reset Cell {self}")
            self.event_generate('<<PostResetDeleteCell>>')  # or reset?

    def _get_current_id(self, connections):
        for id_, connection in connections.items():
            if connection == self:
                return id_

    def __get_cell_connection_frame(self):
        return self.children['cell_connection_frame']

    def __get_cells_frame(self):
        return self.master.master.master

    def _add_connection_frame(self, connection=None, event=False):
        if connection is None:
            connection = ('', '', '', '', '', '', '', '', '')
        cell_connection_frame = self.__get_cell_connection_frame()
        number_of_connections = len(self.connection_dict)
        next_connection_id = number_of_connections + 1

        single_cell_connection = SingleCellConnectionFrame(
            cell_connection_frame, connection, self.available_rmods_list, self.icons,
            borderwidth=0, relief="ridge", name=f"single_cell_connection_{self.connection_iterator}"
        )
        self.connection_iterator += 1
        self.connection_dict[next_connection_id] = single_cell_connection
        single_cell_connection.grid(sticky="EW", pady=2, column=0, columnspan=2)
        if event:
            logger.info(f"Adding cell connection to {self}")
            self.event_generate('<<PostAddConnectionFrame>>')


class SingleCellConnectionFrame(ttk.Frame):

    __DIRECTIONS = ['', 'TX', 'RX', 'TXRX']

    def __init__(self, parent, connection, available_rmods_list, icons, *args, **kwargs):
        super().__init__(parent, *args, **kwargs)
        self.available_rmods_list = available_rmods_list
        self.icons = icons
        self.antl_list = []
        self._initial_setup(connection)

    def get_configuration(self):
        antl_configuration = {i + 1: antl.get() for i, antl in enumerate(self.antl_list)}
        antl_configuration.update({'rmod': self.children['rmod'].get()})
        return antl_configuration

    @property
    def is_fully_configured(self):
        number_of_configured_antennas = len([antl.get() for i, antl in enumerate(self.antl_list) if antl.get()])
        return number_of_configured_antennas >= 1 and self.children['rmod'].get()

    def _initial_setup(self, connection):
        rmod_name, *antls = connection
        rmod = ttk.Combobox(
            self, values=self.available_rmods_list, width=17, state="readonly", name="rmod"
        )
        Tooltip(rmod, text='Select available RMOD')
        rmod.set(rmod_name)
        rmod.grid(row=0, column=0)
        for i in range(1, 9):
            antl_combobox = ttk.Combobox(
                self, values=self.__DIRECTIONS, width=5, state="readonly", name=f"antl_{i}"
            )
            Tooltip(antl_combobox, text=f'Set Channel for antenna {i}')
            antl_combobox.set(antls[i - 1])
            antl_combobox.grid(row=0, column=i)
            self.antl_list.append(antl_combobox)

        delete_single_connection_frame_button = ttk.Button(
            self, text="del", command=lambda: self._destroy_connection(event=True),
            name="delete_single_cell_connection_frame_button", image=self.icons['minus_sign']
        )
        Tooltip(delete_single_connection_frame_button, text='Delete Single Connection')
        delete_single_connection_frame_button.grid(row=0, column=9, padx=(28, 0), sticky="nse")

        reset_single_connection_frame_button = ttk.Button(
            self, text="del", command=lambda: self._reset(event=True),
            name="reset_single_cell_connection_frame_button", image=self.icons['refresh_sign']
        )
        Tooltip(reset_single_connection_frame_button, text='Reset Single Connection')
        reset_single_connection_frame_button.grid(row=0, column=10, sticky="nse")

    def _destroy_connection(self, event=False):
        number_of_connections = len(self.__get_cell_label_frame().connection_dict)
        if event:
            logger.info(f"Deleting Connection {self}")
        if number_of_connections > 1:
            self._destroy(event)
        else:
            self._reset(event)

    def _destroy(self, event=False):
        connections = self.__get_cell_label_frame().connection_dict
        current_id = self._get_current_id(connections)
        connections.pop(current_id)
        self.forget()
        self.__get_cell_label_frame().rearrange()
        if event:
            self.event_generate('<<PostResetDeleteConnection>>')
        self.destroy()

    def _reset(self, event=False):
        for child in self.winfo_children():
            if isinstance(child, ttk.Combobox):
                child.set("")
                child.config(state='readonly')
        if event:
            logger.info(f"Resetting Connection {self}")
            self.event_generate('<<PostResetDeleteConnection>>')

    def __get_cell_label_frame(self):
        return self.master.master

    def __get_cell_connection_frame(self):
        return self.master

    def _get_current_id(self, connections):
        for id_, connection in connections.items():
            if connection == self:
                return id_
